arguments.command:
cat notes/*.md reports/programme/*.md; python -c "
import json;nb=json.load(open('notebooks/fpa_quickcheck_2026-08.ipynb'))
for c in nb['cells']:
  print('---',c['cell_type']);print(''.join(c['source']))
  for o in c.get('outputs',[]): print('>>',''.join(o.get('text','')) if 'text' in o else o.get('data',{}).get('text/plain',''))
"

